<title>Gestion Stock — Prototype</title>
<style>
:root{--nav:#0f172a;--blue:#2563eb;--bg:#f5f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#e5e7eb;--green:#15803d;--red:#dc2626;--shadow:0 8px 30px #0f172a0d}
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",Arial;background:var(--bg);color:var(--text)}button,input,select{font:inherit}.app{display:flex;min-height:100vh}.side{width:245px;background:linear-gradient(180deg,#0f172a,#172554);color:#fff;padding:20px 13px;position:sticky;top:0;height:100vh}.brand{font-weight:800;font-size:18px;padding:8px 12px 24px}.brand small{display:block;color:#94a3b8;font-size:10px;margin-top:3px}.nav button{width:100%;display:block;border:0;background:transparent;color:#cbd5e1;text-align:left;padding:10px 12px;border-radius:9px;margin:3px 0;cursor:pointer}.nav button:hover,.nav button.active{background:#2563eb;color:#fff}.main{flex:1;padding:30px;overflow:auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.date{background:#fff;border:1px solid var(--line);padding:9px 12px;border-radius:9px;color:var(--muted);font-size:12px}.page{display:none}.page.active{display:block}.hero{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-bottom:20px}h1{margin:0 0 5px;font-size:28px}h2{margin:0}.sub{color:var(--muted);font-size:13px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:var(--shadow)}.label{font-size:12px;color:var(--muted);font-weight:700}.value{font-size:23px;font-weight:800;margin-top:8px}.green{color:var(--green)}.red{color:var(--red)}.toolbar{display:flex;justify-content:space-between;gap:10px;margin:16px 0}.btn{border:0;background:var(--blue);color:#fff;padding:9px 13px;border-radius:8px;cursor:pointer;font-weight:700}.btn.gray{background:#eef2f7;color:#344054}.btn.red{background:#dc2626}.btn.small{padding:6px 9px;font-size:12px}.actions{display:flex;gap:6px}.tablewrap{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:auto;box-shadow:var(--shadow)}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:12px 14px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px}th{background:#f8fafc;color:var(--muted);font-size:11px;text-transform:uppercase}tbody tr:hover{background:#f8fbff}.empty{text-align:center;color:#98a2b3;padding:30px}.modal{position:fixed;inset:0;background:#0f172a99;display:none;align-items:center;justify-content:center;padding:20px;z-index:50}.modal.open{display:flex}.box{width:min(540px,95vw);background:#fff;border-radius:15px;padding:23px;box-shadow:0 25px 80px #0004}.box h2{margin-bottom:16px}.field{margin:11px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:8px}.actions-end{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.note{font-size:12px;color:var(--muted);margin-top:8px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.entity-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.search{padding:9px 11px;border:1px solid var(--line);border-radius:8px;width:260px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;color:#3730a3;font-size:11px;font-weight:700}.stocklow{background:#fff7ed;color:#c2410c}.positive{color:var(--green);font-weight:700}.negative{color:var(--red);font-weight:700}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.app{display:block}.side{width:100%;height:auto;position:relative}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap;width:auto}.main{padding:18px}.cards,.entity-grid,.two{grid-template-columns:1fr}.search{width:100%}}
</style>
</head>
<body>
<div class="app">
<aside class="side"><div class="brand">Gestion Stock<small>Administration & pilotage</small></div><div class="nav" id="nav"></div></aside>
<main class="main"><div class="top"><div><b>Espace de gestion</b></div><div class="date" id="today"></div></div>

<section id="dashboard" class="page active"><div class="hero"><div><h1>Dashboard</h1><div class="sub">Vue générale de l'entreprise</div></div></div>
<div class="cards">
<div class="card"><div class="label">Capital</div><div class="value" id="dCapital">0 DH</div></div>
<div class="card"><div class="label">Valeur du stock</div><div class="value" id="dStockValue">0 DH</div></div>
<div class="card"><div class="label">Entrées</div><div class="value green" id="dIn">0 DH</div></div>
<div class="card"><div class="label">Sorties</div><div class="value red" id="dOut">0 DH</div></div>
<div class="card"><div class="label">Résultat</div><div class="value" id="dResult">0 DH</div></div>
<div class="card"><div class="label">Bénéfice</div><div class="value green" id="dProfit">0 DH</div></div>
<div class="card"><div class="label">Produits</div><div class="value" id="dProducts">0</div></div>
<div class="card"><div class="label">Stock total</div><div class="value" id="dQty">0</div></div>
</div></section>

<section id="stock" class="page"><div class="hero"><div><h1>Stock</h1><div class="sub">Stock initial modifiable. Les achats ajoutent et les ventes retirent automatiquement.</div></div><button class="btn" onclick="openModal('stock')">+ Ajouter / modifier stock</button></div><div class="tablewrap"><table><thead><tr><th>Produit</th><th>Quantité</th><th>Prix achat</th><th>Valeur</th><th>Action</th></tr></thead><tbody id="stockBody"></tbody></table></div></section>

<section id="products" class="page"><div class="hero"><div><h1>Produits</h1><div class="sub">Catalogue des produits et prix.</div></div><button class="btn" onclick="openModal('product')">+ Ajouter produit</button></div><div class="toolbar"><input class="search" id="productSearch" placeholder="Rechercher un produit..." oninput="renderProducts()"></div><div class="tablewrap"><table><thead><tr><th>Nom</th><th>Prix achat</th><th>Prix vente</th><th>Stock</th><th>Actions</th></tr></thead><tbody id="productBody"></tbody></table></div></section>

<section id="clients" class="page"><div class="hero"><div><h1>Clients</h1><div class="sub">Nom obligatoire, adresse facultative.</div></div><button class="btn" onclick="openModal('client')">+ Ajouter client</button></div><div class="tablewrap"><table><thead><tr><th>Nom</th><th>Adresse</th><th>Actions</th></tr></thead><tbody id="clientBody"></tbody></table></div></section>

<section id="suppliers" class="page"><div class="hero"><div><h1>Fournisseurs</h1><div class="sub">Nom obligatoire, adresse facultative.</div></div><button class="btn" onclick="openModal('supplier')">+ Ajouter fournisseur</button></div><div class="tablewrap"><table><thead><tr><th>Nom</th><th>Adresse</th><th>Actions</th></tr></thead><tbody id="supplierBody"></tbody></table></div></section>

<section id="purchases" class="page"><div class="hero"><div><h1>Achats</h1><div class="sub">L'achat augmente le stock et crée une sortie dans les mouvements.</div></div><button class="btn" onclick="openModal('purchase')">+ Ajouter achat</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Fournisseur</th><th>Produit</th><th>Qté</th><th>Total</th><th>Actions</th></tr></thead><tbody id="purchaseBody"></tbody></table></div></section>

<section id="sales" class="page"><div class="hero"><div><h1>Ventes</h1><div class="sub">La vente diminue le stock et crée une entrée dans les mouvements.</div></div><button class="btn" onclick="openModal('sale')">+ Ajouter vente</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Client</th><th>Produit</th><th>Qté</th><th>Total</th><th>Actions</th></tr></thead><tbody id="saleBody"></tbody></table></div></section>

<section id="charges" class="page"><div class="hero"><div><h1>Charges</h1></div><button class="btn" onclick="openModal('charge')">+ Ajouter charge</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Description</th><th>Prix</th><th>Actions</th></tr></thead><tbody id="chargeBody"></tbody></table></div></section>

<section id="salaries" class="page"><div class="hero"><div><h1>Salaires</h1><div class="sub">Le salaire est limité au bénéfice disponible.</div></div><button class="btn" onclick="openModal('salary')">+ Ajouter salaire</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Description</th><th>Montant</th><th>Actions</th></tr></thead><tbody id="salaryBody"></tbody></table></div></section>

<section id="capital" class="page"><div class="hero"><div><h1>Capital</h1><div class="sub">Capital initial, apport personnel ou augmentation avec bénéfice.</div></div><button class="btn" onclick="openModal('capital')">+ Ajouter opération</button></div><div class="cards"><div class="card"><div class="label">Capital actuel</div><div class="value" id="capitalValue">0 DH</div></div><div class="card"><div class="label">Bénéfice disponible</div><div class="value green" id="capitalProfit">0 DH</div></div></div><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>Date</th><th>Type</th><th>Montant</th><th>Mouvement</th><th>Actions</th></tr></thead><tbody id="capitalBody"></tbody></table></div></section>

<section id="movements" class="page"><div class="hero"><div><h1>Mouvements</h1><div class="sub">Générés automatiquement selon les opérations.</div></div></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Type</th><th>Produit / Description</th><th>Qté</th><th>Prix entrée</th><th>Prix sortie</th></tr></thead><tbody id="movementBody"></tbody><tfoot><tr><th colspan="4">Totaux</th><th id="totalIn">0 DH</th><th id="totalOut">0 DH</th></tr></tfoot></table></div></section>

<section id="result" class="page"><div class="hero"><div><h1>Résultat</h1><div class="sub">Synthèse financière selon les mouvements enregistrés.</div></div></div><div class="cards"><div class="card"><div class="label">Total entrées</div><div class="value green" id="rIn">0 DH</div></div><div class="card"><div class="label">Total sorties</div><div class="value red" id="rOut">0 DH</div></div><div class="card"><div class="label">Résultat</div><div class="value" id="rResult">0 DH</div></div><div class="card"><div class="label">Bénéfice</div><div class="value green" id="rProfit">0 DH</div></div></div></section>
</main></div>

<div class="modal" id="modal"><div class="box"><h2 id="modalTitle"></h2><div id="modalForm"></div><div class="actions-end"><button class="btn gray" onclick="closeModal()">Annuler</button><button class="btn" onclick="submitModal()">Enregistrer</button></div></div></div>

<script>
let db={products:[],clients:[],suppliers:[],purchases:[],sales:[],charges:[],salaries:[],capital:[],totals:{ins:0,outs:0,result:0,capital:0,profit:0}}, modalType=null, editId=null;
const csrf=document.querySelector('meta[name="csrf-token"]')?.content || '';
function money(n){return Number(n||0).toLocaleString('fr-MA',{minimumFractionDigits:2,maximumFractionDigits:2})+' DH'}
function today(){return new Date().toLocaleDateString('fr-FR')}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function product(id){return db.products.find(x=>String(x.id)===String(id))}
function client(id){return db.clients.find(x=>String(x.id)===String(id))}
function supplier(id){return db.suppliers.find(x=>String(x.id)===String(id))}
function productName(id){return product(id)?.name||'Produit sans nom'}
function clientName(id){return client(id)?.name||'—'}
function supplierName(id){return supplier(id)?.name||'—'}
function rows(id,html,cols=6){document.getElementById(id).innerHTML=html||`<tr><td colspan="${cols}" class="empty">Aucune donnée</td></tr>`}
async function api(url,method='GET',body=null){const opts={method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf}};if(body)opts.body=JSON.stringify(body);const r=await fetch(url,opts);let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(' ')||'Une erreur est survenue.');return data}
async function load(){db=await api('/gestion/state');renderAll()}
function show(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));document.getElementById('n-'+id).classList.add('active');renderAll()}
const navItems=[['dashboard','Dashboard'],['stock','Stock'],['products','Produits'],['clients','Clients'],['suppliers','Fournisseurs'],['purchases','Achats'],['sales','Ventes'],['charges','Charges'],['salaries','Salaires'],['capital','Capital'],['movements','Mouvements'],['result','Résultat']];
document.getElementById('nav').innerHTML=navItems.map((x,i)=>`<button id="n-${x[0]}" class="${i===0?'active':''}" onclick="show('${x[0]}')">${x[1]}</button>`).join('');
document.getElementById('today').textContent=today();
function renderProducts(){const q=(document.getElementById('productSearch')?.value||'').toLowerCase();rows('productBody',db.products.filter(p=>p.name.toLowerCase().includes(q)).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${money(p.buy_price)}</td><td>${money(p.sell_price)}</td><td>${p.stock_quantity}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('product',${p.id})">Modifier</button><button class="btn small red" onclick="del('product',${p.id})">Supprimer</button></div></td></tr>`).join(''),5)}
function renderAll(){const t=db.totals;document.getElementById('dCapital').textContent=money(t.capital);document.getElementById('dStockValue').textContent=money(db.products.reduce((s,p)=>s+p.stock_quantity*Number(p.buy_price),0));document.getElementById('dIn').textContent=money(t.ins);document.getElementById('dOut').textContent=money(t.outs);document.getElementById('dResult').textContent=money(t.result);document.getElementById('dProfit').textContent=money(t.profit);document.getElementById('dProducts').textContent=db.products.length;document.getElementById('dQty').textContent=db.products.reduce((s,p)=>s+p.stock_quantity,0);document.getElementById('capitalValue').textContent=money(t.capital);document.getElementById('capitalProfit').textContent=money(t.profit);document.getElementById('rIn').textContent=money(t.ins);document.getElementById('rOut').textContent=money(t.outs);document.getElementById('rResult').textContent=money(t.result);document.getElementById('rProfit').textContent=money(t.profit);renderProducts();rows('stockBody',db.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stock_quantity}</td><td>${money(p.buy_price)}</td><td>${money(p.stock_quantity*Number(p.buy_price))}</td><td><button class="btn small gray" onclick="openModal('stock',${p.id})">Modifier</button></td></tr>`).join(''),5);rows('clientBody',db.clients.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.address)||'—'}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('client',${x.id})">Modifier</button><button class="btn small red" onclick="del('client',${x.id})">Supprimer</button></div></td></tr>`).join(''),3);rows('supplierBody',db.suppliers.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.address)||'—'}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('supplier',${x.id})">Modifier</button><button class="btn small red" onclick="del('supplier',${x.id})">Supprimer</button></div></td></tr>`).join(''),3);rows('purchaseBody',db.purchases.map(x=>`<tr><td>${x.date}</td><td>${esc(x.supplier?.name||supplierName(x.supplier_id))}</td><td>${esc(x.product?.name||productName(x.product_id))}</td><td>${x.quantity}</td><td>${money(x.total)}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('purchase',${x.id})">Modifier</button><button class="btn small red" onclick="del('purchase',${x.id})">Supprimer</button></div></td></tr>`).join(''),6);rows('saleBody',db.sales.map(x=>`<tr><td>${x.date}</td><td>${esc(x.client?.name||clientName(x.client_id))}</td><td>${esc(x.product?.name||productName(x.product_id))}</td><td>${x.quantity}</td><td>${money(x.total)}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('sale',${x.id})">Modifier</button><button class="btn small red" onclick="del('sale',${x.id})">Supprimer</button></div></td></tr>`).join(''),6);rows('chargeBody',db.charges.map(x=>`<tr><td>${x.date}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('charge',${x.id})">Modifier</button><button class="btn small red" onclick="del('charge',${x.id})">Supprimer</button></div></td></tr>`).join(''),4);rows('salaryBody',db.salaries.map(x=>`<tr><td>${x.date}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('salary',${x.id})">Modifier</button><button class="btn small red" onclick="del('salary',${x.id})">Supprimer</button></div></td></tr>`).join(''),4);rows('capitalBody',db.capital.map(x=>`<tr><td>${x.date}</td><td>${esc(x.type)}</td><td>${money(x.amount)}</td><td>${x.movement?'<span class="badge">Entrée</span>':'<span class="badge">Aucun mouvement</span>'}</td><td><div class="actions"><button class="btn small gray" onclick="openModal('capital',${x.id})">Modifier</button><button class="btn small red" onclick="del('capital',${x.id})">Supprimer</button></div></td></tr>`).join(''),5);const ms=[];db.capital.filter(x=>x.movement).forEach(x=>ms.push({date:x.date,type:'Capital',desc:x.type,qty:'',in:Number(x.amount),out:0}));db.purchases.forEach(x=>ms.push({date:x.date,type:'Achat',desc:x.product?.name||productName(x.product_id),qty:x.quantity,in:0,out:Number(x.total)}));db.sales.forEach(x=>ms.push({date:x.date,type:'Vente',desc:x.product?.name||productName(x.product_id),qty:x.quantity,in:Number(x.total),out:0}));db.charges.forEach(x=>ms.push({date:x.date,type:'Charge',desc:x.description,qty:'',in:0,out:Number(x.amount)}));db.salaries.forEach(x=>ms.push({date:x.date,type:'Salaire',desc:x.description,qty:'',in:0,out:Number(x.amount)}));rows('movementBody',ms.map(x=>`<tr><td>${x.date}</td><td>${x.type}</td><td>${esc(x.desc)}</td><td>${x.qty}</td><td class="positive">${x.in?money(x.in):'—'}</td><td class="negative">${x.out?money(x.out):'—'}</td></tr>`).join(''),6);document.getElementById('totalIn').textContent=money(t.ins);document.getElementById('totalOut').textContent=money(t.outs)}
function options(arr,selected,labelFn){return '<option value="">— Sélectionner —</option>'+arr.map(x=>`<option value="${x.id}" ${String(x.id)===String(selected)?'selected':''}>${esc(labelFn(x))}</option>`).join('')}
function field(label,html){return `<div class="field"><label>${label}</label>${html}</div>`}
function getRecord(type,id){const map={product:'products',stock:'products',client:'clients',supplier:'suppliers',purchase:'purchases',sale:'sales',charge:'charges',salary:'salaries',capital:'capital'};return db[map[type]]?.find(x=>String(x.id)===String(id))||null}
function openModal(type,id=null){modalType=type;editId=id;const old=getRecord(type,id);modalTitle.textContent=(id?'Modifier ':'Ajouter ')+({product:'un produit',stock:'le stock',client:'un client',supplier:'un fournisseur',purchase:'un achat',sale:'une vente',charge:'une charge',salary:'un salaire',capital:'une opération de capital'}[type]);let f='';if(type==='product')f=field('Nom',`<input id="f-name" required value="${esc(old?.name)}">`)+`<div class="two">${field("Prix d'achat",`<input id="f-buy" type="number" min="0" step="0.01" value="${old?.buy_price??0}">`)}${field('Prix de vente',`<input id="f-sell" type="number" min="0" step="0.01" value="${old?.sell_price??0}">`)}</div>`;if(type==='stock')f=field('Produit',`<select id="f-product">${options(db.products,old?.id,x=>x.name)}</select>`)+field('Quantité en stock',`<input id="f-qty" type="number" min="0" step="1" value="${old?.stock_quantity??0}">`);if(type==='client')f=field('Nom',`<input id="f-name" required value="${esc(old?.name)}">`)+field('Adresse (facultatif)',`<input id="f-address" value="${esc(old?.address)}">`);if(type==='supplier')f=field('Nom',`<input id="f-name" required value="${esc(old?.name)}">`)+field('Adresse (facultatif)',`<input id="f-address" value="${esc(old?.address)}">`);if(type==='purchase')f=field('Fournisseur',`<select id="f-supplier" required>${options(db.suppliers,old?.supplier_id,x=>x.name)}</select>`)+field('Produit',`<select id="f-product" required>${options(db.products,old?.product_id,x=>x.name)}</select>`)+field('Quantité',`<input id="f-qty" type="number" min="1" step="1" value="${old?.quantity??1}">`)+`<div class="note">Total = quantité × prix d'achat. L'argent disponible est contrôlé par le serveur.</div>`;if(type==='sale')f=field('Client',`<select id="f-client" required>${options(db.clients,old?.client_id,x=>x.name)}</select>`)+field('Produit',`<select id="f-product" required>${options(db.products,old?.product_id,x=>x.name)}</select>`)+field('Quantité',`<input id="f-qty" type="number" min="1" step="1" value="${old?.quantity??1}">`)+`<div class="note">Total = quantité × prix de vente. Le stock est contrôlé par le serveur.</div>`;if(type==='charge')f=field('Description',`<input id="f-desc" required value="${esc(old?.description)}">`)+field('Prix',`<input id="f-amount" type="number" min="0.01" step="0.01" value="${old?.amount??''}">`);if(type==='salary')f=field('Description',`<input id="f-desc" required value="${esc(old?.description)}">`)+field('Montant',`<input id="f-amount" type="number" min="0.01" step="0.01" value="${old?.amount??''}">`)+`<div class="note">Bénéfice disponible : <b>${money(db.totals.profit+(old?Number(old.amount):0))}</b></div>`;if(type==='capital')f=field('Type',`<select id="f-ctype"><option>Capital initial</option><option>Augmentation - apport personnel</option><option>Augmentation - bénéfice</option></select>`)+field('Montant',`<input id="f-amount" type="number" min="0.01" step="0.01" value="${old?.amount??''}">`)+`<div class="note">Apport personnel = Prix entrée. Augmentation avec bénéfice = aucun nouveau mouvement.</div>`;modalForm.innerHTML=f;if(old&&type==='capital')document.getElementById('f-ctype').value=old.type;document.getElementById('modal').classList.add('open')}
function closeModal(){document.getElementById('modal').classList.remove('open');modalType=null;editId=null}
function val(id){return document.getElementById(id)?.value||''}
async function submitModal(){try{const t=modalType,id=editId;let url='',method=id?'PUT':'POST',body={};if(t==='product'){body={name:val('f-name').trim(),buy_price:Number(val('f-buy')),sell_price:Number(val('f-sell'))};url=id?`/gestion/products/${id}`:'/gestion/products'}else if(t==='stock'){body={stock_quantity:Number(val('f-qty'))};url=`/gestion/products/${id}/stock`}else if(t==='client'||t==='supplier'){body={name:val('f-name').trim(),address:val('f-address').trim()};url=`/gestion/${t==='client'?'clients':'suppliers'}${id?'/'+id:''}`}else if(t==='purchase'){body={supplier_id:Number(val('f-supplier')),product_id:Number(val('f-product')),quantity:Number(val('f-qty'))};url=id?`/gestion/purchases/${id}`:'/gestion/purchases'}else if(t==='sale'){body={client_id:Number(val('f-client')),product_id:Number(val('f-product')),quantity:Number(val('f-qty'))};url=id?`/gestion/sales/${id}`:'/gestion/sales'}else if(t==='charge'){body={description:val('f-desc').trim(),amount:Number(val('f-amount'))};url=id?`/gestion/charges/${id}`:'/gestion/charges'}else if(t==='salary'){body={description:val('f-desc').trim(),amount:Number(val('f-amount'))};url=id?`/gestion/salaries/${id}`:'/gestion/salaries'}else if(t==='capital'){body={type:val('f-ctype'),amount:Number(val('f-amount'))};url=id?`/gestion/capital/${id}`:'/gestion/capital'}await api(url,method,body);closeModal();await load()}catch(e){alert(e.message)}}
async function del(type,id){if(!confirm('Confirmer la suppression ?'))return;try{const urls={product:`/gestion/products/${id}`,client:`/gestion/clients/${id}`,supplier:`/gestion/suppliers/${id}`,purchase:`/gestion/purchases/${id}`,sale:`/gestion/sales/${id}`,charge:`/gestion/charges/${id}`,salary:`/gestion/salaries/${id}`,capital:`/gestion/capital/${id}`};await api(urls[type],'DELETE');await load()}catch(e){alert(e.message)}}
load().catch(e=>alert(e.message));
</script></body></html><?php /**PATH C:\Users\pc\Desktop\yassine\gestion_stock_laravel\resources\views/gestion.blade.php ENDPATH**/ ?>